class DatabaseConnection implements AutoCloseable {
    private String dbName;

    // Constructor: guarantees the connection is "open" the moment the object exists
    public DatabaseConnection(String dbName) {
        this.dbName = dbName;
        System.out.println("Connection to " + dbName + " opened");
    }

    public void query(String sql) {
        System.out.println("Running on " + dbName + ": " + sql);
    }

    @Override
    public void close() { // NOT a real destructor, just a regular method Java calls for you
        System.out.println("Connection to " + dbName + " closed");
    }
}

public class Main {
    public static void main(String[] args) {
        // try-with-resources guarantees close() runs, even if an exception happens inside
        try (DatabaseConnection conn = new DatabaseConnection("OrdersDB")) {
            conn.query("SELECT * FROM orders");
        }
        System.out.println("Block finished, connection already closed");
    }
}

