class DatabaseConnection:
    def __init__(self, db_name):  # constructor: guarantees the connection is "open" immediately
        self.db_name = db_name
        print(f"Connection to {db_name} opened")

    def query(self, sql):
        print(f"Running on {self.db_name}: {sql}")

    def close(self):
        print(f"Connection to {self.db_name} closed")

    def __enter__(self):  # lets this class work with Python's "with" statement
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()  # guaranteed to run when the with block ends, even on an exception


if __name__ == "__main__":
    with DatabaseConnection("OrdersDB") as conn:
        conn.query("SELECT * FROM orders")

    print("Block finished, connection already closed")

codes.cpp:
#include <iostream>
#include <string>
using namespace std;

class DatabaseConnection {
private:
    string dbName;

public:
    // Constructor: guarantees the connection is "open" the moment the object exists
    DatabaseConnection(string dbName) : dbName(dbName) {
        cout << "Connection to " << dbName << " opened" << endl;
    }

    void query(string sql) {
        cout << "Running on " << dbName << ": " << sql << endl;
    }

    // Destructor: runs AUTOMATICALLY and DETERMINISTICALLY when the object goes out of scope
    ~DatabaseConnection() {
        cout << "Connection to " << dbName << " closed" << endl;
    }
};

int main() {
    {
        DatabaseConnection conn("OrdersDB");
        conn.query("SELECT * FROM orders");
    } // conn goes out of scope HERE, its destructor runs automatically, right now

    cout << "Block finished, connection already closed" << endl;
    return 0;
}
